import { z } from 'zod';
import { sha256 } from '../sha256';
import { sourceRangeSchema, sourceFileSchema, sourceFileHash, sourceRangeText, type AgentContextSourceRange } from './agentContextSource';

export const AGENT_CONTEXT_MAX_BYTES = 16 * 1024 * 1024;
const id = z.string().min(1).max(200);
const text = z.object({ type: z.literal('text'), text: z.string().max(1_000_000) }).strict();
const constituent = z.union([text, sourceRangeSchema]);
export const contextSectionSchema = z.object({
  type: z.literal('section'), name: z.string().trim().min(1).max(120),
  content: z.array(constituent).min(1).max(1000)
}).strict();
export type ContextSection = z.infer<typeof contextSectionSchema>;
const contextBlock = z.union([constituent, contextSectionSchema]);
const toolCall = z.object({ type: z.literal('toolCall'), id, name: id, arguments: z.record(z.string(), z.json()) }).strict();
const timestamp = z.number().int().nonnegative().default(0);
export const agentContextMessageSchema = z.discriminatedUnion('role', [
  z.object({ role: z.literal('user'), content: z.array(contextBlock).min(1).max(1000), timestamp }).strict(),
  z.object({ role: z.literal('assistant'), content: z.array(z.union([contextBlock, toolCall])).min(1).max(1000), timestamp }).strict(),
  z.object({ role: z.literal('toolResult'), toolCallId: id, toolName: id,
    content: z.array(contextBlock).min(1).max(1000), isError: z.boolean().default(false), timestamp }).strict()
]);
export type AgentContextMessage = z.infer<typeof agentContextMessageSchema>;
export function agentContextSourceRanges(messages: readonly AgentContextMessage[]): AgentContextSourceRange[] {
  const references: AgentContextSourceRange[] = [];
  for (const message of messages) for (const block of message.content) {
    if (block.type === 'sourceRange') references.push(block);
    else if (block.type === 'section') for (const child of block.content) if (child.type === 'sourceRange') references.push(child);
  }
  return references;
}
function snapshotVersion(messages: readonly AgentContextMessage[]) {
  return messages.some(m => m.content.some(b => b.type === 'section')) ? 3 : agentContextSourceRanges(messages).length ? 2 : 1;
}
/** Preserve section boundaries in the model input without changing the stored structure. */
export function agentContextModelContent(content: AgentContextMessage['content']) {
  return content.flatMap(block => {
    const blocks = block.type === 'section'
      ? [{ type: 'text' as const, text: `[ContextSection: ${JSON.stringify(block.name)}]` }, ...block.content,
        { type: 'text' as const, text: '[/ContextSection]' }] : [block];
    return blocks.map(child => {
      if (child.type === 'sourceRange') throw Error('AGENT_CONTEXT_UNRESOLVED: resolve source ranges before model conversion');
      return child;
    });
  });
}
const entrySchema = z.object({ id, parentId: id.nullable(), message: agentContextMessageSchema }).strict();
export const agentTrajectorySchema = z.object({
  agentType: z.string().regex(/^[a-z][a-z0-9_-]{0,63}$/), sourceSessionId: id,
  format: z.literal('messages-v1'), fromEntryId: id, throughEntryId: id,
  entries: z.array(entrySchema).min(1).max(2000)
}).strict();
export type AgentTrajectoryInput = z.input<typeof agentTrajectorySchema>;
const snapshotDataSchema = z.object({
  version: z.union([z.literal(1), z.literal(2), z.literal(3)]),
  source: agentTrajectorySchema.pick({ agentType: true, sourceSessionId: true, format: true }),
  range: agentTrajectorySchema.pick({ fromEntryId: true, throughEntryId: true }),
  messages: z.array(agentContextMessageSchema).min(1).max(2000)
}).strict();
export const agentContextSnapshotSchema = snapshotDataSchema.extend({ contentHash: z.string().regex(/^[a-f0-9]{64}$/),
  sourceFiles: z.record(z.string().regex(/^[a-f0-9]{64}$/), sourceFileSchema).optional() });
export type AgentContextSnapshot = z.infer<typeof agentContextSnapshotSchema>;

/** Canonical JSON also stabilizes tool arguments whose object key order differs. */
function canonical(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  if (value !== null && typeof value === 'object') return `{${Object.keys(value).sort()
    .map(key => `${JSON.stringify(key)}:${canonical((value as Record<string, unknown>)[key])}`).join(',')}}`;
  return JSON.stringify(value);
}
function bounded(input: unknown) {
  if (new TextEncoder().encode(JSON.stringify(input)).byteLength > AGENT_CONTEXT_MAX_BYTES)
    throw Error(`AGENT_CONTEXT_TOO_LARGE: context exceeds ${AGENT_CONTEXT_MAX_BYTES / 1024 / 1024} MiB`);
}
function validateMessages(messages: AgentContextMessage[]) {
  const pending = new Map<string, string>(), seen = new Set<string>();
  for (const message of messages) {
    if (message.role === 'toolResult') {
      if (pending.get(message.toolCallId) !== message.toolName)
        throw Error('INVALID_AGENT_CONTEXT: orphan, duplicate or mismatched tool result');
      pending.delete(message.toolCallId);
    } else {
      if (pending.size) throw Error('INVALID_AGENT_CONTEXT: missing tool results before next message');
      if (message.role === 'assistant') for (const block of message.content) if (block.type === 'toolCall') {
        if (seen.has(block.id)) throw Error('INVALID_AGENT_CONTEXT: duplicate tool call ID');
        seen.add(block.id); pending.set(block.id, block.name);
      }
    }
  }
  if (pending.size) throw Error('INVALID_AGENT_CONTEXT: slice ends before tool results');
}

/** Captured trajectory value. All parsing/conversion lives here; no SDK or I/O dependency. */
export class AgentContext {
  readonly #snapshot: AgentContextSnapshot;
  private constructor(snapshot: AgentContextSnapshot) { this.#snapshot = structuredClone(snapshot); }
  get contentHash() { return this.#snapshot.contentHash; }

  static fromTrajectory(raw: unknown): AgentContext {
    bounded(raw);
    const input = agentTrajectorySchema.parse(raw);
    const entries = new Map(input.entries.map(entry => [entry.id, entry]));
    if (entries.size !== input.entries.length) throw Error('INVALID_AGENT_CONTEXT: duplicate entry ID');
    const selected: AgentContextMessage[] = [], visited = new Set<string>();
    let cursor: string | null = input.throughEntryId;
    while (cursor !== null) {
      if (visited.has(cursor)) throw Error('INVALID_AGENT_CONTEXT: cyclic trajectory');
      visited.add(cursor);
      const entry = entries.get(cursor);
      if (!entry) throw Error('INVALID_AGENT_CONTEXT: missing entry on selected branch');
      selected.push(entry.message);
      if (cursor === input.fromEntryId) break;
      cursor = entry.parentId;
    }
    if (cursor !== input.fromEntryId) throw Error('INVALID_AGENT_CONTEXT: range is not on one branch');
    const messages = selected.reverse();
    validateMessages(messages);
    const data = snapshotDataSchema.parse({ version: snapshotVersion(messages),
      source: { agentType: input.agentType, sourceSessionId: input.sourceSessionId, format: input.format },
      range: { fromEntryId: input.fromEntryId, throughEntryId: input.throughEntryId }, messages });
    return new AgentContext({ ...data, contentHash: sha256(canonical(data)) });
  }

  /** Capture a complete conversation while retaining its panel-owned identity. */
  static fromMessages(sourceSessionId: string, messages: readonly AgentContextMessage[]): AgentContext {
    return AgentContext.fromTrajectory({ agentType: 'diagram-composer', sourceSessionId, format: 'messages-v1',
      fromEntryId: 'message-0', throughEntryId: `message-${messages.length - 1}`,
      entries: messages.map((message, index) => ({ id: `message-${index}`, parentId: index ? `message-${index - 1}` : null, message })) });
  }

  static fromSnapshot(raw: unknown): AgentContext {
    bounded(raw);
    const snapshot = agentContextSnapshotSchema.parse(raw);
    const { contentHash, sourceFiles, ...data } = snapshot;
    const references = agentContextSourceRanges(snapshot.messages);
    if (references.length && snapshot.version < 2) throw Error('INVALID_AGENT_CONTEXT: source ranges require version 2 or later');
    if (snapshot.messages.some(m => m.content.some(b => b.type === 'section')) && snapshot.version !== 3)
      throw Error('INVALID_AGENT_CONTEXT: sections require version 3');
    for (const [hash, file] of Object.entries(sourceFiles ?? {})) {
      if (sourceFileHash(file) !== hash) throw Error('INVALID_AGENT_CONTEXT: source file hash mismatch');
      if (!references.some(ref => ref.version.kind === 'snapshot' && ref.version.contentHash === hash))
        throw Error('INVALID_AGENT_CONTEXT: unreferenced source file');
    }
    for (const ref of references) if (ref.version.kind === 'snapshot' && sourceFiles?.[ref.version.contentHash])
      sourceRangeText(ref, sourceFiles[ref.version.contentHash]);
    if (contentHash !== sha256(canonical(data))) throw Error('INVALID_AGENT_CONTEXT: content hash mismatch');
    validateMessages(snapshot.messages);
    return new AgentContext(snapshot);
  }

  toSnapshot(): AgentContextSnapshot { return structuredClone(this.#snapshot); }

  /** Source attachments are portable transport data, excluded from the immutable descriptor hash. */
  withoutSourceFiles(): AgentContextSnapshot {
    const { sourceFiles: _, ...snapshot } = this.toSnapshot(); return snapshot;
  }

  withMessages(messages: unknown, sourceFiles?: AgentContextSnapshot['sourceFiles']): AgentContext {
    const parsed = z.array(agentContextMessageSchema).parse(messages);
    const data = snapshotDataSchema.parse({ version: snapshotVersion(parsed),
      source: this.#snapshot.source, range: this.#snapshot.range, messages: parsed });
    return AgentContext.fromSnapshot({ ...data, contentHash: sha256(canonical(data)), ...(sourceFiles && Object.keys(sourceFiles).length ? { sourceFiles } : {}) });
  }

  async resolveSources(read?: (reference: AgentContextSourceRange) => Promise<string>): Promise<AgentContext> {
    const snapshot = this.toSnapshot(), cache = new Map<string, Promise<string>>();
    const messages = [];
    let bytes = 0;
    const resolve = async (block: z.infer<typeof constituent>) => {
      if (block.type !== 'sourceRange') return [block];
      const key = canonical(block);
      let pending = cache.get(key);
      if (!pending) {
        const file = block.version.kind === 'snapshot' ? snapshot.sourceFiles?.[block.version.contentHash] : undefined;
        pending = file ? Promise.resolve(sourceRangeText(block, file)) : read ? read(block) : Promise.reject(Error('AGENT_CONTEXT_SOURCE_UNAVAILABLE'));
        cache.set(key, pending);
      }
      const text = await pending;
      bytes += new TextEncoder().encode(text).byteLength;
      if (bytes > AGENT_CONTEXT_MAX_BYTES) throw Error(`AGENT_CONTEXT_TOO_LARGE: expanded sources exceed ${AGENT_CONTEXT_MAX_BYTES / 1024 / 1024} MiB`);
      const resolved = [];
      for (let offset = 0; offset < text.length || offset === 0; offset += 1_000_000)
        resolved.push({ type: 'text' as const, text: text.slice(offset, offset + 1_000_000) });
      return resolved;
    };
    for (const message of snapshot.messages) {
      const content = [];
      for (const block of message.content) {
        if (block.type === 'section') {
          const children = [];
          for (const child of block.content) children.push(...await resolve(child));
          content.push({ ...block, content: children });
        } else if (block.type === 'toolCall') content.push(block);
        else content.push(...await resolve(block));
      }
      messages.push({ ...message, content });
    }
    const data = snapshotDataSchema.parse({ version: snapshot.messages.some(m => m.content.some(b => b.type === 'section')) ? 3 : 1, source: snapshot.source, range: snapshot.range, messages });
    return AgentContext.fromSnapshot({ ...data, contentHash: sha256(canonical(data)) });
  }

  toPiMessages() {
    return this.toSnapshot().messages.map(original => {
      const content = agentContextModelContent(original.content);
      const message = original.role === 'assistant' ? { ...original, content } : { ...original, content: content.filter(block => block.type === 'text') };
      if (message.role !== 'assistant') return message;
      // Synthetic provenance marks imported history; it never selects the run's model.
      return { ...message, api: 'openai-responses' as const, provider: 'agent-context', model: this.#snapshot.source.agentType,
        stopReason: message.content.some(block => block.type === 'toolCall') ? 'toolUse' as const : 'stop' as const,
        usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0,
          cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } } };
    });
  }
}

import { z } from 'zod';
import { sha256 } from '../sha256';

const hash = z.string().regex(/^[a-f0-9]{64}$/);
export const sourcePathSchema = z.string().min(1).max(1000).refine(path =>
  !/^[\\/]|^[A-Za-z]:|[\\\0]/.test(path) && path.split('/').every(part => part && part !== '.' && part !== '..'), 'Expected a relative source path');
export const sourceRangeSchema = z.object({
  type: z.literal('sourceRange'), sourceId: z.string().min(1).max(200), path: sourcePathSchema,
  startLine: z.number().int().positive(), endLine: z.number().int().positive(),
  version: z.discriminatedUnion('kind', [
    z.object({ kind: z.literal('git'), commit: z.string().regex(/^(?:[a-f0-9]{40}|[a-f0-9]{64})$/) }).strict(),
    z.object({ kind: z.literal('snapshot'), contentHash: hash }).strict()
  ])
}).strict().refine(value => value.endLine >= value.startLine, 'Invalid source range');
export type AgentContextSourceRange = z.infer<typeof sourceRangeSchema>;
/** A captured file, or an existing evidence slice whose original line offset is retained. */
export const sourceFileSchema = z.object({ startLine: z.number().int().positive(), lines: z.array(z.string()).min(1) }).strict();
export type AgentContextSourceFile = z.infer<typeof sourceFileSchema>;
export function sourceFileHash(file: AgentContextSourceFile) { return sha256(JSON.stringify({ startLine: file.startLine, lines: file.lines })); }
export function sourceRangeText(reference: AgentContextSourceRange, file: AgentContextSourceFile) {
  const start = reference.startLine - file.startLine, end = reference.endLine - file.startLine + 1;
  if (start < 0 || end > file.lines.length) throw Error('AGENT_CONTEXT_SOURCE_RANGE: range is outside the pinned source');
  return `${reference.path}:${reference.startLine}-${reference.endLine}\n${file.lines.slice(start, end).join('\n')}`;
}
export const captureSourceRangeSchema = z.object({
  type: z.literal('sourceFile'), sourceId: z.string().min(1).max(200), path: sourcePathSchema,
  startLine: z.number().int().positive().default(1), endLine: z.number().int().positive().optional(),
  revision: z.string().min(1).max(200).optional()
}).strict().refine(value => value.endLine === undefined || value.endLine >= value.startLine, 'Invalid source range');
export type CaptureSourceRange = z.infer<typeof captureSourceRangeSchema>;

import { z } from 'zod';
import { captureSourceRangeSchema } from './agentContextSource';
import { agentContextSnapshotSchema, contextSectionSchema } from './agentContext';

export const savedAgentContextIdSchema = z.string().regex(/^saved-agent-context-[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/);
export const agentContextGroupSchema = z.string().trim().min(1).max(120);
const contentHashSchema = z.string().regex(/^[a-f0-9]{64}$/);
export const agentContextLineageSchema = z.object({
  parentAgentContextId: savedAgentContextIdSchema, parentContentHash: contentHashSchema
}).strict();
export const agentContextCommentSchema = z.object({
  commentId: z.string().uuid(), text: z.string().trim().min(1).max(2000),
  createdAt: z.string().datetime(), contentHash: contentHashSchema
}).strict();
export const forkAgentContextSchema = z.object({
  requestId: z.string().uuid().toLowerCase(), agentContextId: savedAgentContextIdSchema,
  expectedContentHash: contentHashSchema, name: z.string().trim().min(1).max(120),
  description: z.string().trim().max(2000).optional(), group: agentContextGroupSchema.nullable().optional()
}).strict();
export const addAgentContextCommentSchema = z.object({
  requestId: z.string().uuid().toLowerCase(), agentContextId: savedAgentContextIdSchema,
  expectedContentHash: contentHashSchema, text: z.string().trim().min(1).max(2000)
}).strict();
const captureConstituentSchema = z.union([z.object({ type: z.literal('text'), text: z.string().min(1).max(1_000_000) }).strict(), captureSourceRangeSchema]);
export const captureContextSectionSchema = contextSectionSchema.extend({ content: z.array(captureConstituentSchema).min(1).max(1000) });
export const createAgentContextSchema = z.object({
  requestId: z.string().uuid().toLowerCase(), name: z.string().trim().min(1).max(120),
  description: z.string().trim().max(2000).default(''),
  group: agentContextGroupSchema.optional(),
  context: z.union([z.string().trim().min(1).max(1_000_000), agentContextSnapshotSchema, z.array(z.union([captureConstituentSchema, captureContextSectionSchema])).min(1).max(1000)])
}).strict();
export const readAgentContextSchema = z.object({ agentContextId: savedAgentContextIdSchema }).strict();
export const updateAgentContextSchema = z.object({ agentContextId: savedAgentContextIdSchema, group: agentContextGroupSchema.nullable() }).strict();
export const listAgentContextsSchema = z.object({ query: z.string().max(200).default(''), offset: z.number().int().nonnegative().default(0), limit: z.number().int().min(1).max(100).default(20) }).strict();
export const savedAgentContextSchema = z.object({
  schemaVersion: z.literal(1), agentContextId: savedAgentContextIdSchema,
  name: z.string(), description: z.string(), createdAt: z.string().datetime(), requestHash: z.string(),
  group: agentContextGroupSchema.optional(),
  lineage: agentContextLineageSchema.optional(),
  comments: z.array(agentContextCommentSchema).optional(),
  snapshot: agentContextSnapshotSchema
}).strict();
export type SavedAgentContext = z.infer<typeof savedAgentContextSchema>;
export function summarizeAgentContext(record: SavedAgentContext) {
  return { agentContextId: record.agentContextId, name: record.name, description: record.description, createdAt: record.createdAt,
    ...(record.group !== undefined ? { group: record.group } : {}),
    ...(record.lineage ? { lineage: record.lineage } : {}),
    ...(record.comments ? { comments: record.comments } : {}),
    contentHash: record.snapshot.contentHash, messageCount: record.snapshot.messages.length, source: record.snapshot.source };
}
export const agentContextToolDefinitions = [
  { name: 'fork-agent-context' as const, schema: forkAgentContextSchema, description: 'Fork a saved AgentContext into a new saved ID, copying its pinned snapshot and recording parent ID and expectedContentHash as lineage. Requires name and UUID requestId; inherits description and group unless overridden (group:null clears it). Comments remain on the original. Retry identical arguments/requestId safely, even after editing the fork. Edit the fork on disk, recompute its snapshot hash, and add a one-sentence change explanation with add-agent-context-comment before use. Requires Workspace access; no canvas needed.' },
  { name: 'add-agent-context-comment' as const, schema: addAgentContextCommentSchema, description: 'Append a metadata comment to a saved AgentContext without changing model-visible content or its hash. Supply UUID requestId, agentContextId, current expectedContentHash, and text. The comment records this content hash and timestamp. Repeating identical arguments/requestId adds no duplicate. Requires Workspace access; no canvas needed.' },
  { name: 'read-agent-context-lineage' as const, schema: readAgentContextSchema, description: 'Trace saved AgentContext ancestors from root to the selected context, returning metadata and whether each pinned parent hash still matches its current parent. Reads no model-visible text and launches no model. Missing or cyclic ancestry fails explicitly.' },
  { name: 'update-agent-context' as const, schema: updateAgentContextSchema, description: 'Set saved AgentContext group metadata, or clear it with group: null. Does not change the immutable context snapshot or contentHash. Requires Workspace access; no live canvas is needed. Repeating the same assignment is safe.' },
  { name: 'create-agent-context' as const, schema: createAgentContextSchema, description: 'Save reusable context to disk and return its global agentContextId and contentHash. Supply name, optional description and group metadata, context (plain text, a validated AgentContextSnapshot, or an array of text/sourceFile constituents and ContextSections). A ContextSection is {type:"section", name, content:[text/sourceFile constituents]}: one named level inside this context, distinct from the outer group. Sections preserve order, are included in the content hash, and are rendered with labeled boundaries to the model. A sourceFile specifies a registered sourceId, relative path, optional 1-based inclusive startLine/endLine, and optional Git revision. Files are pinned at creation and resolved lazily; unchanged Git files need no copied source blob. Supply a unique UUID requestId. Context is explicit: this does not capture the current chat automatically. IDs work across canvases and chats in this application store and survive restarts. Retry the same arguments/requestId after an uncertain outcome. Requires Workspace access.' },
  { name: 'list-agent-contexts' as const, schema: listAgentContextsSchema, description: 'Browse saved AgentContexts by name/description with query, offset and limit. Returns summaries and nextOffset, without loading conversation text into the chat. IDs can be passed to gen-alternatives or prompt-driven diagram generation.' },
  { name: 'read-agent-context' as const, schema: readAgentContextSchema, description: 'Read one immutable saved AgentContext by global agentContextId, including its compact snapshot and contentHash. Source references are expanded separately in resolvedSnapshot when present; the saved snapshot and its hash remain unchanged. This does not change the current conversation or launch a model.' }
];

import { AgentContext, type AgentContextSnapshot } from '../agents/agentContext';
import { sourceFileHash, type AgentContextSourceFile, type AgentContextSourceRange } from '../agents/agentContextSource';
import { sha256 } from '../sha256';
import type { Diagram } from './diagram';

export interface DiagramAgentContextStore {
  put(snapshot: AgentContextSnapshot): Promise<string>;
  get(recordId: string): Promise<unknown>;
  portable?(snapshot: AgentContextSnapshot): Promise<AgentContextSnapshot>;
  resolve?(snapshot: AgentContextSnapshot): Promise<AgentContextSnapshot>;
}

interface DiagramAgentContextIdentity {
  diagramId: string;
  compiledFromRevisionId: string;
  sourceFingerprint: string;
}

export type StoredDiagramAgentContext = DiagramAgentContextIdentity & {
  backingRecordId: string; contentHash: string; snapshot?: never;
};
export type InlineDiagramAgentContext = DiagramAgentContextIdentity & {
  snapshot: AgentContextSnapshot; contentHash?: string; backingRecordId?: never;
};
/** The diagram carries a small disk reference. Inline snapshots remain valid for old workspaces and portable exports. */
export type DiagramAgentContext = StoredDiagramAgentContext | InlineDiagramAgentContext;

export function diagramContextSourceFingerprint(diagram: Diagram): string {
  return sha256(JSON.stringify({ binding: diagram.sourceContext.binding ?? null, evidence: diagram.sourceContext.evidence }));
}

/** Capture stable source evidence once; the current diagram is supplied by each later generation request. */
export function compileDiagramAgentContext(diagram: Diagram): InlineDiagramAgentContext {
  const sourceFingerprint = diagramContextSourceFingerprint(diagram);
  const sourceFiles: Record<string, AgentContextSourceFile> = {};
  const references: AgentContextSourceRange[] = [];
  const evidence = Object.fromEntries(Object.entries(diagram.sourceContext.evidence).map(([id, entry]) => [id, {
    ...entry, sourceRanges: entry.sourceRanges.map(({ originalLines, ...range }) => {
      const file = { startLine: range.startLine, lines: [...originalLines] }, contentHash = sourceFileHash(file);
      sourceFiles[contentHash] = file;
      const reference: AgentContextSourceRange = { type: 'sourceRange', sourceId: entry.sourceId ?? diagram.sourceContext.binding?.sourceId ?? diagram.diagramId,
        path: range.path, startLine: range.startLine, endLine: range.endLine, version: { kind: 'snapshot', contentHash } };
      references.push(reference);
      return { ...range, source: reference };
    })
  }]));
  const context = AgentContext.fromTrajectory({ agentType: 'diagram-context', sourceSessionId: diagram.diagramId,
    format: 'messages-v1', fromEntryId: 'source', throughEntryId: 'source', entries: [{ id: 'source', parentId: null,
      message: { role: 'user', timestamp: 0, content: [{ type: 'text', text: `Source evidence for diagram ${diagram.diagramId}. This is background captured at revision ${diagram.revisionId}; use the current diagram supplied with each edit request as the authoritative content.\n${JSON.stringify({ binding: diagram.sourceContext.binding ?? null, evidence })}` }, ...references] } }] });
  return { diagramId: diagram.diagramId, compiledFromRevisionId: diagram.revisionId, sourceFingerprint,
    contentHash: context.contentHash, snapshot: AgentContext.fromSnapshot({ ...context.toSnapshot(), ...(references.length ? { sourceFiles } : {}) }).toSnapshot() };
}

export async function storeDiagramAgentContext(value: DiagramAgentContext, store: DiagramAgentContextStore): Promise<StoredDiagramAgentContext> {
  validateDiagramAgentContext(value);
  if (!value.snapshot) return value as StoredDiagramAgentContext;
  const backingRecordId = await store.put(value.snapshot);
  if (!/^[a-f0-9]{64}$/.test(backingRecordId)) throw Error('Invalid diagram context backing record');
  return { diagramId: value.diagramId, compiledFromRevisionId: value.compiledFromRevisionId,
    sourceFingerprint: value.sourceFingerprint, contentHash: value.snapshot.contentHash, backingRecordId };
}

export async function loadDiagramAgentContext(value: DiagramAgentContext, store?: DiagramAgentContextStore): Promise<AgentContextSnapshot> {
  validateDiagramAgentContext(value);
  const raw = value.snapshot ?? (store && value.backingRecordId ? await store.get(value.backingRecordId) : undefined);
  if (!raw) throw Error('AGENT_CONTEXT_STORAGE_UNAVAILABLE: diagram context backing record cannot be loaded');
  const snapshot = AgentContext.fromSnapshot(raw).toSnapshot();
  if ((value.contentHash && snapshot.contentHash !== value.contentHash) || snapshot.source.agentType !== 'diagram-context'
    || snapshot.source.sourceSessionId !== value.diagramId) throw Error('DIAGRAM_CONTEXT_MISMATCH: backing record does not match diagram');
  return snapshot;
}

export function validateDiagramAgentContext(value: DiagramAgentContext): void {
  if (!value || typeof value.diagramId !== 'string' || !value.diagramId.startsWith('diagram-')
    || typeof value.compiledFromRevisionId !== 'string' || !value.compiledFromRevisionId.startsWith('diagram-revision-')
    || typeof value.sourceFingerprint !== 'string' || !/^[a-f0-9]{64}$/.test(value.sourceFingerprint)
    || value.contentHash !== undefined && !/^[a-f0-9]{64}$/.test(value.contentHash)) throw Error('Invalid diagram agent context');
  if ('snapshot' in value && value.snapshot !== undefined) {
    if (value.backingRecordId !== undefined) throw Error('Diagram context has two backing sources');
    const snapshot = AgentContext.fromSnapshot(value.snapshot).toSnapshot();
    if ((value.contentHash && snapshot.contentHash !== value.contentHash) || snapshot.source.agentType !== 'diagram-context'
      || snapshot.source.sourceSessionId !== value.diagramId) throw Error('Diagram agent context belongs to another diagram');
  } else if (!value.contentHash || typeof value.backingRecordId !== 'string' || !/^[a-f0-9]{64}$/.test(value.backingRecordId))
    throw Error('Invalid diagram context backing record');
}

import type { AgentContextSources } from '../../core/ports/agentContextSources';
import type { AgentContextRepository } from '../../core/ports/agentContextRepository';
import { AgentContext, agentContextSourceRanges } from '../../../domain/core/agents/agentContext';
import type { CaptureSourceRange } from '../../../domain/core/agents/agentContextSource';
import { createAgentContextSchema, forkAgentContextSchema, addAgentContextCommentSchema, listAgentContextsSchema, readAgentContextSchema, updateAgentContextSchema, summarizeAgentContext } from '../../../domain/core/agents/savedAgentContext';
import { sha256 } from '../../../domain/core/sha256';

export class AgentContextLibrary {
  constructor(private readonly store: AgentContextRepository, private readonly sources?: AgentContextSources) {}
  async fork(raw: unknown) {
    const input = forkAgentContextSchema.parse(raw);
    const requestHash = sha256(JSON.stringify(['fork', input]));
    const agentContextId = `saved-agent-context-${input.requestId}`;
    const previous = await this.store.read(agentContextId);
    if (previous) {
      if (previous.requestHash !== requestHash) throw Error('REQUEST_ID_CONFLICT: this UUID identifies a different saved context');
      return summarizeAgentContext(previous);
    }
    const parent = await this.store.read(input.agentContextId);
    if (!parent) throw Error('AGENT_CONTEXT_NOT_FOUND: parent context is unavailable');
    if (parent.snapshot.contentHash !== input.expectedContentHash) throw Error('AGENT_CONTEXT_CHANGED: reread the parent before forking');
    const group = input.group === undefined ? parent.group : input.group ?? undefined;
    return summarizeAgentContext(await this.store.create({ schemaVersion: 1, agentContextId,
      name: input.name, description: input.description ?? parent.description, ...(group !== undefined ? { group } : {}),
      createdAt: new Date().toISOString(), requestHash, snapshot: parent.snapshot,
      lineage: { parentAgentContextId: parent.agentContextId, parentContentHash: parent.snapshot.contentHash } }));
  }
  async addComment(raw: unknown) {
    return summarizeAgentContext(await this.store.addComment(addAgentContextCommentSchema.parse(raw)));
  }
  async lineage(raw: unknown) {
    const { agentContextId } = readAgentContextSchema.parse(raw);
    const ancestors = [], seen = new Set<string>();
    let id: string | undefined = agentContextId;
    while (id) {
      if (seen.has(id)) throw Error('INVALID_AGENT_CONTEXT_LINEAGE: cyclic ancestry');
      seen.add(id);
      const record = await this.store.read(id);
      if (!record) throw Error('AGENT_CONTEXT_NOT_FOUND: ancestor is unavailable');
      ancestors.push(summarizeAgentContext(record)); id = record.lineage?.parentAgentContextId;
    }
    return { items: ancestors.reverse().map((item, index, items) => ({ ...item,
      ...(item.lineage ? { parentMatches: index > 0 && item.lineage.parentContentHash === items[index - 1].contentHash } : {}) })) };
  }
  async create(raw: unknown) {
    const input = createAgentContextSchema.parse(raw);
    // Preserve legacy creation hashes when no group was supplied. Metadata updates never rewrite this receipt.
    const groupHashInput = input.group === undefined ? [] : [input.group];
    const constituentRequestHash = Array.isArray(input.context) ? sha256(JSON.stringify([input.name, input.description, input.context, ...groupHashInput])) : undefined;
    if (constituentRequestHash) {
      const previous = await this.store.read(`saved-agent-context-${input.requestId}`);
      if (previous) {
        if (previous.requestHash !== constituentRequestHash) throw Error('REQUEST_ID_CONFLICT: this UUID identifies a different saved context');
        return summarizeAgentContext(previous);
      }
    }
    let content: import('../../../domain/core/agents/agentContext').AgentContextMessage['content'] | undefined;
    if (typeof input.context === 'string') content = [{ type: 'text', text: input.context }];
    else if (Array.isArray(input.context)) {
      content = [];
      // Bound peak capture memory even for many file constituents.
      const capture = async (block: CaptureSourceRange | { type: 'text'; text: string }) => {
        if (block.type === 'text') return block;
        else {
          if (!this.sources) throw Error('AGENT_CONTEXT_SOURCE_UNAVAILABLE');
          return this.sources.capture(block);
        }
      };
      for (const block of input.context) {
        if (block.type === 'section') {
          const children = [];
          for (const child of block.content) children.push(await capture(child));
          content.push({ ...block, content: children });
        } else content.push(await capture(block));
      }
    }
    const context = content ? AgentContext.fromTrajectory({
      agentType: 'saved-context', sourceSessionId: input.requestId, format: 'messages-v1', fromEntryId: 'context', throughEntryId: 'context',
      entries: [{ id: 'context', parentId: null, message: { role: 'user', content, timestamp: 0 } }]
    }) : AgentContext.fromSnapshot(input.context);
    const requestHash = constituentRequestHash ?? sha256(JSON.stringify([input.name, input.description, context.contentHash, ...groupHashInput]));
    if (!constituentRequestHash) {
      const previous = await this.store.read(`saved-agent-context-${input.requestId}`);
      if (previous) {
        if (previous.requestHash !== requestHash) throw Error('REQUEST_ID_CONFLICT: this UUID identifies a different saved context');
        return summarizeAgentContext(previous);
      }
    }
    const snapshot = this.sources ? await this.sources.persist(context.toSnapshot()) : context.toSnapshot();
    const record = await this.store.create({ schemaVersion: 1, agentContextId: `saved-agent-context-${input.requestId}`,
      name: input.name, description: input.description, ...(input.group !== undefined ? { group: input.group } : {}), createdAt: new Date().toISOString(), snapshot,
      requestHash });
    return summarizeAgentContext(record);
  }
  async update(raw: unknown) {
    const { agentContextId, group } = updateAgentContextSchema.parse(raw);
    return summarizeAgentContext(await this.store.updateGroup(agentContextId, group));
  }
  async read(id: string, resolveSources = true) {
    readAgentContextSchema.parse({ agentContextId: id });
    const record = await this.store.read(id);
    if (!record) throw Error('AGENT_CONTEXT_NOT_FOUND: saved context is unavailable');
    const snapshot = AgentContext.fromSnapshot(record.snapshot).toSnapshot();
    const resolvedSnapshot = resolveSources && agentContextSourceRanges(snapshot.messages).length
      ? (await AgentContext.fromSnapshot(snapshot).resolveSources(this.sources ? ref => this.sources!.read(ref) : undefined)).toSnapshot() : undefined;
    return { ...summarizeAgentContext(record), snapshot, ...(resolvedSnapshot ? { resolvedSnapshot } : {}) };
  }
  async list(raw: unknown = {}) {
    const { query, offset, limit } = listAgentContextsSchema.parse(raw);
    const items = (await this.store.summaries()).filter(item => `${item.name}\n${item.description}`.toLowerCase().includes(query.toLowerCase()))
      .sort((a, b) => b.createdAt.localeCompare(a.createdAt) || a.agentContextId.localeCompare(b.agentContextId));
    return { items: items.slice(offset, offset + limit), nextOffset: offset + limit < items.length ? offset + limit : null };
  }
}

import { randomUUID } from 'node:crypto';
import { mkdir, readFile, readdir, open, link, rename, rm } from 'node:fs/promises';
import path from 'node:path';
import { setTimeout as delay } from 'node:timers/promises';
import { AgentContext } from '../../../domain/core/agents/agentContext';
import { savedAgentContextIdSchema, savedAgentContextSchema, summarizeAgentContext, updateAgentContextSchema, addAgentContextCommentSchema, type SavedAgentContext } from '../../../domain/core/agents/savedAgentContext';
import type { AgentContextRepository } from '../../../application/core/ports/agentContextRepository';

/** Globally addressable within this application store; no canvas or chat binding. */
export class FileAgentContextRepository implements AgentContextRepository {
  private readonly directory: string;
  constructor(root: string) { this.directory = path.join(root, 'agent-contexts'); }
  private file(id: string) { return path.join(this.directory, `${savedAgentContextIdSchema.parse(id)}.json`); }
  async read(id: string): Promise<SavedAgentContext | null> {
    try {
      const record = savedAgentContextSchema.parse(JSON.parse(await readFile(this.file(id), 'utf8')));
      if (record.agentContextId !== id) throw Error('AGENT_CONTEXT_ID_MISMATCH');
      AgentContext.fromSnapshot(record.snapshot);
      return record;
    } catch (error) { if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null; throw error; }
  }
  async create(record: SavedAgentContext) {
    const file = this.file(record.agentContextId);
    await mkdir(this.directory, { recursive: true });
    const temp = path.join(this.directory, `.${randomUUID()}.tmp`);
    try {
      const handle = await open(temp, 'wx', 0o600);
      try { await handle.writeFile(JSON.stringify(record)); await handle.sync(); } finally { await handle.close(); }
      // An atomic, exclusive publish also protects identical IDs across processes.
      try { await link(temp, file); }
      catch (error) { if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error; }
      const directory = await open(this.directory, 'r');
      try { await directory.sync(); } finally { await directory.close(); }
      const saved = (await this.read(record.agentContextId))!;
      if (saved.requestHash !== record.requestHash) throw Error('REQUEST_ID_CONFLICT: this UUID identifies a different saved context');
      return saved;
    } finally { await rm(temp, { force: true }); }
  }
  async updateGroup(id: string, group: string | null) {
    const input = updateAgentContextSchema.parse({ agentContextId: id, group });
    return this.mutateMetadata(id, record => {
      if (input.group === null) delete record.group;
      else record.group = input.group;
    });
  }
  async addComment(raw: Parameters<AgentContextRepository['addComment']>[0]) {
    const input = addAgentContextCommentSchema.parse(raw);
    return this.mutateMetadata(input.agentContextId, record => {
      const previous = record.comments?.find(comment => comment.commentId === input.requestId);
      if (previous) {
        if (previous.text !== input.text || previous.contentHash !== input.expectedContentHash)
          throw Error('REQUEST_ID_CONFLICT: this UUID identifies a different comment');
        return;
      }
      if (record.snapshot.contentHash !== input.expectedContentHash) throw Error('AGENT_CONTEXT_CHANGED: reread the context before commenting');
      (record.comments ??= []).push({ commentId: input.requestId, text: input.text,
        contentHash: input.expectedContentHash, createdAt: new Date().toISOString() });
    });
  }
  private async mutateMetadata(id: string, mutate: (record: SavedAgentContext) => void) {
    await mkdir(this.directory, { recursive: true });
    const lock = `${this.file(id)}.lock`, deadline = Date.now() + 5000;
    // Coordinate metadata writers across repository instances and backend processes.
    for (;;) {
      try { await mkdir(lock); break; }
      catch (error) {
        if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error;
        if (Date.now() >= deadline) throw Error('AGENT_CONTEXT_BUSY: metadata is locked; retry after the writer finishes');
        await delay(10);
      }
    }
    const temp = path.join(this.directory, `.${randomUUID()}.tmp`);
    try {
      const record = await this.read(id);
      if (!record) throw Error('AGENT_CONTEXT_NOT_FOUND: saved context is unavailable');
      mutate(record);
      savedAgentContextSchema.parse(record);
      const handle = await open(temp, 'wx', 0o600);
      try { await handle.writeFile(JSON.stringify(record)); await handle.sync(); } finally { await handle.close(); }
      await rename(temp, this.file(id));
      const directory = await open(this.directory, 'r');
      try { await directory.sync(); } finally { await directory.close(); }
      return record;
    } finally {
      try { await rm(temp, { force: true }); } finally { await rm(lock, { recursive: true, force: true }); }
    }
  }
  async summaries() {
    let files: string[];
    try { files = await readdir(this.directory); }
    catch (error) { if ((error as NodeJS.ErrnoException).code === 'ENOENT') return []; throw error; }
    const summaries: ReturnType<typeof summarizeAgentContext>[] = [];
    for (const file of files) if (/^saved-agent-context-[a-f0-9-]{36}\.json$/.test(file)) {
      const record = await this.read(file.slice(0, -5)); if (record) summaries.push(summarizeAgentContext(record));
    }
    return summaries;
  }
}

import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import path from 'node:path';
import type { AgentContextSources } from '../../../application/core/ports/agentContextSources';
import { AgentContext, agentContextSourceRanges, AGENT_CONTEXT_MAX_BYTES, type AgentContextSnapshot } from '../../../domain/core/agents/agentContext';
import { sourceRangeSchema, sourceFileSchema, sourceFileHash, sourceRangeText, captureSourceRangeSchema,
  type AgentContextSourceFile, type AgentContextSourceRange, type CaptureSourceRange } from '../../../domain/core/agents/agentContextSource';
import type { CorpusBinding } from '../../../domain/core/profiles/domainProfile';
import { corpusProvider } from '../corpus/corpus';
import { ImmutableRecords } from './immutableRecords';

const exec = promisify(execFile);
/** Shared across saved contexts and diagram contexts. No caller-supplied absolute file paths. */
export class FileAgentContextSources implements AgentContextSources {
  private readonly blobs: ImmutableRecords;
  private readonly pinned = new Map<string, Promise<AgentContextSourceFile>>();
  constructor(root: string, private readonly binding?: (sourceId: string) => Promise<CorpusBinding>) {
    this.blobs = new ImmutableRecords(path.join(root, 'agent-context-sources'));
  }
  private async source(id: string) {
    if (!this.binding) throw Error('AGENT_CONTEXT_SOURCE_UNAVAILABLE: source registry is unavailable');
    return this.binding(id);
  }
  private async git(binding: CorpusBinding, args: string[]) {
    if (binding.kind !== 'git-worktree') throw Error('AGENT_CONTEXT_SOURCE_UNAVAILABLE: source is not Git');
    return (await exec('git', ['--no-replace-objects', '-C', binding.root, ...args], { encoding: 'utf8', maxBuffer: AGENT_CONTEXT_MAX_BYTES })).stdout;
  }
  private file(text: string): AgentContextSourceFile {
    if (Buffer.byteLength(text) > AGENT_CONTEXT_MAX_BYTES) throw Error('AGENT_CONTEXT_TOO_LARGE: source exceeds 2 MiB');
    if (text.includes('\0')) throw Error('AGENT_CONTEXT_SOURCE_INVALID: binary source');
    return { startLine: 1, lines: text.split(/\r?\n/) };
  }
  private pinnedFile(binding: CorpusBinding, commit: string, file: string) {
    const key = JSON.stringify([binding.root, commit, file]);
    let pending = this.pinned.get(key);
    if (!pending) {
      pending = this.readPinnedFile(binding, commit, file);
      // Each file is at most 2 MiB. Repeated ranges share one read; failures are retryable.
      this.pinned.set(key, pending);
      while (this.pinned.size > 16) this.pinned.delete(this.pinned.keys().next().value!);
      void pending.catch(() => { if (this.pinned.get(key) === pending) this.pinned.delete(key); });
    }
    return pending;
  }
  private async readPinnedFile(binding: CorpusBinding, commit: string, file: string) {
    // Reject trees, submodules and symlinks instead of treating their payload as source text.
    const entry = await this.git(binding, ['ls-tree', commit, '--', file]);
    if (!/^100(?:644|755) blob /.test(entry) || entry.trimEnd().split('\n').length !== 1)
      throw Error('AGENT_CONTEXT_SOURCE_UNAVAILABLE: expected a regular Git file');
    return this.file(await this.git(binding, ['show', `${commit}:${file}`]));
  }
  async capture(raw: CaptureSourceRange) {
    const input = captureSourceRangeSchema.parse(raw), binding = await this.source(input.sourceId);
    let file: AgentContextSourceFile, version: AgentContextSourceRange['version'];
    const revision = input.revision ?? (binding.kind === 'git-worktree' ? binding.revision : undefined);
    if (revision) {
      const commit = (await this.git(binding, ['rev-parse', '--verify', '--end-of-options', `${revision}^{commit}`])).trim();
      file = await this.pinnedFile(binding, commit, input.path); version = { kind: 'git', commit };
    } else {
      file = this.file(await corpusProvider(binding).readDocumentText(binding, input.path));
      version = { kind: 'snapshot', contentHash: sourceFileHash(file) };
      if (binding.kind === 'git-worktree') {
        // Reuse committed bytes only when they exactly match the captured worktree content.
        try {
          const commit = (await this.git(binding, ['rev-parse', '--verify', 'HEAD^{commit}'])).trim();
          const committed = await this.pinnedFile(binding, commit, input.path);
          if (sourceFileHash(committed) === sourceFileHash(file)) version = { kind: 'git', commit };
        } catch { /* Untracked files and unborn repositories use a shared immutable snapshot. */ }
      }
    }
    const reference = sourceRangeSchema.parse({ type: 'sourceRange', sourceId: input.sourceId, path: input.path,
      startLine: input.startLine, endLine: input.endLine ?? file.startLine + file.lines.length - 1, version });
    sourceRangeText(reference, file);
    if (version.kind === 'snapshot') await this.blobs.put(file);
    return reference;
  }
  private async load(reference: AgentContextSourceRange) {
    sourceRangeSchema.parse(reference);
    const file = reference.version.kind === 'snapshot'
      ? sourceFileSchema.parse(await this.blobs.get(reference.version.contentHash))
      : await this.pinnedFile(await this.source(reference.sourceId), reference.version.commit, reference.path);
    sourceRangeText(reference, file);
    return file;
  }
  async read(reference: AgentContextSourceRange) { return sourceRangeText(reference, await this.load(reference)); }
  async persist(raw: AgentContextSnapshot) {
    const context = AgentContext.fromSnapshot(raw), snapshot = context.toSnapshot();
    for (const file of Object.values(snapshot.sourceFiles ?? {})) await this.blobs.put(file);
    // Check references before publication, including imported descriptors with missing blobs.
    const seen = new Set<string>();
    for (const block of agentContextSourceRanges(snapshot.messages)) {
      const key = JSON.stringify(block);
      if (!seen.has(key)) { await this.load(block); seen.add(key); }
    }
    return context.withoutSourceFiles();
  }
  async portable(raw: AgentContextSnapshot) {
    const context = AgentContext.fromSnapshot(raw), snapshot = context.toSnapshot();
    const files: Record<string, AgentContextSourceFile> = {};
    const references = new Map<string, AgentContextSourceRange>();
    for (const block of agentContextSourceRanges(snapshot.messages)) {
      const key = JSON.stringify(block);
      if (references.has(key)) continue;
      const file = block.version.kind === 'snapshot' && snapshot.sourceFiles?.[block.version.contentHash]
        || await this.load(block);
      // Portable context contains only its selected evidence, not unrelated file lines.
      const selected = { startLine: block.startLine,
        lines: file.lines.slice(block.startLine - file.startLine, block.endLine - file.startLine + 1) };
      const contentHash = sourceFileHash(selected); files[contentHash] = selected;
      references.set(key, { ...block, version: { kind: 'snapshot', contentHash } });
    }
    const replace = (block: { type: string }) => block.type === 'sourceRange' ? references.get(JSON.stringify(block))! : block;
    const messages = snapshot.messages.map(message => ({ ...message, content: message.content.map(block => block.type === 'section'
      ? { ...block, content: block.content.map(replace) } : replace(block)) }));
    return context.withMessages(messages, files).toSnapshot();
  }
}
